pid_t pid = fork();

if (pid == -1) {
    // Failure to create process
    perror("fork failed");
    return -1;
}

if (pid == 0) {
    // Code specific to the CHILD process
    // getpid() returns the child's PID
    // getppid() returns the parent's PID
    execvp("ls", args); // Often used to run a new program
} else {
    // Code specific to the PARENT process
    // pid holds the PID of the new child
    wait(NULL); // Wait for child to terminate
}
